        code: `// 26. Standard Stack - Approach 7: RPN Evaluator
#include <iostream>
#include <vector>
#include <string>
#include <stack>
using namespace std;

int evalRPN(const vector<string>& tokens) {
    stack<int> st;
    for (const string& t : tokens) {
        if (t == "+" || t == "-" || t == "*" || t == "/") {
            int b = st.top(); st.pop();
            int a = st.top(); st.pop();
            if (t == "+") st.push(a + b);
            else if (t == "-") st.push(a - b);
            else if (t == "*") st.push(a * b);
            else if (t == "/") st.push(a / b);
        } else {
            st.push(stoi(t));
        }
    }
    return st.top();
}

int main() {
    vector<string> expr = {"2", "1", "+", "3", "*"};
    cout << "RPN (2+1)*3 = " << evalRPN(expr) << endl;
    return 0;
}`,
