        code: `// 27. Standard Queue - Approach 8: Circular Buffer
#include <iostream>
using namespace std;

class CircularQueue {
private:
    int data[5];
    int head = 0, tail = 0, sz = 0, cap = 5;
public:
    bool enqueue(int val) {
        if (sz == cap) return false;
        data[tail] = val;
        tail = (tail + 1) % cap;
        sz++;
        return true;
    }
    int dequeue() {
        if (sz == 0) return -1;
        int val = data[head];
        head = (head + 1) % cap;
        sz--;
        return val;
    }
};

int main() {
    CircularQueue cq;
    cq.enqueue(10); cq.enqueue(20); cq.enqueue(30);
    cout << "Dequeued: " << cq.dequeue() << endl;
    return 0;
}`,
