        code: `// 51. BST - Approach 5: Delete Node
#include <iostream>
using namespace std;

struct BSTNode {
    int val;
    BSTNode* left;
    BSTNode* right;
    BSTNode(int v) : val(v), left(nullptr), right(nullptr) {}
};

BSTNode* findMin(BSTNode* node) {
    while (node->left) node = node->left;
    return node;
}

BSTNode* deleteNode(BSTNode* root, int key) {
    if (!root) return nullptr;
    if (key < root->val) root->left = deleteNode(root->left, key);
    else if (key > root->val) root->right = deleteNode(root->right, key);
    else {
        if (!root->left) {
            BSTNode* temp = root->right;
            delete root;
            return temp;
        } else if (!root->right) {
            BSTNode* temp = root->left;
            delete root;
            return temp;
        }
        BSTNode* temp = findMin(root->right);
        root->val = temp->val;
        root->right = deleteNode(root->right, temp->val);
    }
    return root;
}

void printInorder(BSTNode* root) {
    if (!root) return;
    printInorder(root->left);
    cout << root->val << " ";
    printInorder(root->right);
}

int main() {
    BSTNode* root = new BSTNode(50);
    root->left = new BSTNode(30); root->right = new BSTNode(70);
    root->left->left = new BSTNode(20); root->left->right = new BSTNode(40);

    root = deleteNode(root, 30);
    cout << "Inorder after deleting 30: ";
    printInorder(root);
    cout << endl;
    return 0;
}`,
