        code: `// 54. Graph BFS - Approach 4: Bipartite Check
#include <iostream>
#include <vector>
#include <queue>
using namespace std;

bool isBipartite(int n, const vector<vector<int>>& adj) {
    vector<int> color(n, -1);

    for (int i = 0; i < n; i++) {
        if (color[i] == -1) {
            color[i] = 0;
            queue<int> q;
            q.push(i);
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int v : adj[u]) {
                    if (color[v] == -1) {
                        color[v] = 1 - color[u];
                        q.push(v);
                    } else if (color[v] == color[u]) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

int main() {
    int n = 4;
    vector<vector<int>> adj(n);
    // Square graph (bipartite)
    adj[0] = {1, 3}; adj[1] = {0, 2}; adj[2] = {1, 3}; adj[3] = {0, 2};
    cout << "Is Bipartite: " << (isBipartite(n, adj) ? "Yes" : "No") << endl;
    return 0;
}`,
