        code: `// 80. Coroutines - Approach 1: Sequence Generator
#include <iostream>
#include <coroutine>
using namespace std;

template<typename T>
struct Generator {
    struct promise_type {
        T current_value;
        Generator get_return_object() {
            return Generator{coroutine_handle<promise_type>::from_promise(*this)};
        }
        suspend_always initial_suspend() { return {}; }
        suspend_always final_suspend() noexcept { return {}; }
        suspend_always yield_value(T value) {
            current_value = value;
            return {};
        }
        void return_void() {}
        void unhandled_exception() { terminate(); }
    };

    coroutine_handle<promise_type> handle;
    Generator(coroutine_handle<promise_type> h) : handle(h) {}
    ~Generator() { if (handle) handle.destroy(); }

    bool move_next() {
        if (handle && !handle.done()) {
            handle.resume();
            return !handle.done();
        }
        return false;
    }
    T current_value() const { return handle.promise().current_value; }
};

Generator<int> countUp(int n) {
    for (int i = 1; i <= n; i++) co_yield i;
}

int main() {
    auto gen = countUp(3);
    while (gen.move_next()) cout << gen.current_value() << " "; // 1 2 3
    cout << endl;
    return 0;
}`,
