        code: `// 84. Trie - Approach 9: Longest Common Prefix
#include <iostream>
#include <string>
#include <vector>
using namespace std;

struct Node { Node* children[26] = {nullptr}; bool isWord = false; int childCount = 0; };

class LcpTrie {
    Node* root = new Node();
public:
    void insert(const string& w) {
        Node* curr = root;
        for (char c : w) {
            int idx = c - 'a';
            if (!curr->children[idx]) {
                curr->children[idx] = new Node();
                curr->childCount++;
            }
            curr = curr->children[idx];
        }
        curr->isWord = true;
    }

    string findLCP() {
        string lcp = "";
        Node* curr = root;
        while (curr && curr->childCount == 1 && !curr->isWord) {
            for (int i = 0; i < 26; i++) {
                if (curr->children[i]) {
                    lcp += char('a' + i);
                    curr = curr->children[i];
                    break;
                }
            }
        }
        return lcp;
    }
};

int main() {
    LcpTrie t; t.insert("flower"); t.insert("flow"); t.insert("flight");
    cout << "Longest Common Prefix: " << t.findLCP() << endl; // "fl"
    return 0;
}`,
