        code: `// 90. Floyd-Warshall - Approach 6: Graph Center
#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

const int INF = 1e9;

int findGraphCenter(int n, vector<vector<int>>& dist) {
    for (int k = 0; k < n; k++)
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (dist[i][k] < INF && dist[k][j] < INF)
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);

    int minMaxDist = INT_MAX, centerNode = -1;
    for (int i = 0; i < n; i++) {
        int maxDist = 0;
        for (int j = 0; j < n; j++) {
            if (dist[i][j] != INF) maxDist = max(maxDist, dist[i][j]);
        }
        if (maxDist < minMaxDist) {
            minMaxDist = maxDist;
            centerNode = i;
        }
    }
    return centerNode;
}

int main() {
    vector<vector<int>> dist = {
        {0, 1, INF},
        {1, 0, 1},
        {INF, 1, 0}
    };
    cout << "Graph Center Node: " << findGraphCenter(3, dist) << endl; // 1 (Node 1 is central!)
    return 0;
}`,
