        code: `// 90. Floyd-Warshall - Approach 7: Threshold Neighbors
#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

const int INF = 1e9;

int findTheCity(int n, vector<vector<int>>& dist, int distanceThreshold) {
    for (int k = 0; k < n; k++)
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (dist[i][k] < INF && dist[k][j] < INF)
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);

    int minReachable = INT_MAX, bestCity = -1;
    for (int i = 0; i < n; i++) {
        int count = 0;
        for (int j = 0; j < n; j++) {
            if (i != j && dist[i][j] <= distanceThreshold) count++;
        }
        if (count <= minReachable) {
            minReachable = count;
            bestCity = i;
        }
    }
    return bestCity;
}

int main() {
    vector<vector<int>> dist = {
        {0, 3, INF},
        {3, 0, 1},
        {INF, 1, 0}
    };
    cout << "Best City (Threshold 2): " << findTheCity(3, dist, 2) << endl; // 2
    return 0;
}`,
